def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    marker = max((x for x in counts if x != bg), key=lambda x: counts[x])

    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    if not cells:
        return [row[:] for row in grid]

    minr = min(r for r, c, v in cells)
    maxr = max(r for r, c, v in cells)
    minc = min(c for r, c, v in cells)
    maxc = max(c for r, c, v in cells)
    ar, ac = (minr + maxr) // 2, (minc + maxc) // 2

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for rr, cc, value in cells:
                    nr, nc = r + rr - ar, c + cc - ac
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr][nc] = value
    return out
